from pathlib import Path

def shell(title, description, eyebrow, heading, intro, image, alt, body, active):
    items=[('Web','../web/index.html'),('IT','../it/index.html'),('Hosting','../hosting/index.html'),('Design','../design/index.html')]
    child=''.join(f'<a href="{url}"'+(' aria-current="page"' if name==active else '')+f'>{name}</a>' for name,url in items)
    desktop=f'<div class="nav-group"><a class="nav-parent" href="../services/index.html">Services <span>⌄</span></a><div class="nav-children">{child}</div></div><a href="../portfolio/index.html">Work</a><a href="../about/index.html">About</a><a href="../news/index.html">News</a>'
    mobile='<a href="../services/index.html">Services</a>'+''.join(f'<a class="nav-child-link" href="{url}"'+(' aria-current="page"' if name==active else '')+f'>↳ {name}</a>' for name,url in items)+'<a href="../portfolio/index.html">Work</a><a href="../about/index.html">About</a><a href="../news/index.html">News</a><a href="../contact/index.html">Contact</a>'
    return f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{description}"><title>{title} — Three AM Web + IT</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="../styles.css"></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="shell header-inner"><a class="brand" href="../index.html" aria-label="Three AM home"><img src="../audit/assets/original-path/wp-content/uploads/2019/09/logo-dark.webp" alt="Three AM Web + IT"></a><nav class="desktop-nav" aria-label="Primary navigation">{desktop}</nav><a class="header-contact" href="../contact/index.html">Start a conversation <span>↗</span></a><button class="menu-button" type="button" aria-expanded="false" aria-controls="mobile-menu"><span></span><span></span><span></span><span class="sr-only">Open menu</span></button></div><nav id="mobile-menu" class="mobile-nav" aria-label="Mobile navigation" hidden>{mobile}</nav></header><main id="main"><section class="page-hero"><div class="shell page-hero-grid"><div><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="../index.html">Home</a><span>/</span><a href="../services/index.html">Services</a><span>/</span><span aria-current="page">{title}</span></nav><p class="eyebrow light"><span></span> {eyebrow}</p><h1>{heading}</h1><p class="intro">{intro}</p></div><aside class="hero-side-image"><img src="{image}" alt="{alt}"><span>{eyebrow}</span></aside></div></section><section class="section"><div class="shell content-grid"><aside class="side-nav" aria-label="Services navigation"><p>Services</p><a href="../web/index.html">Web <span>↗</span></a><a href="../it/index.html">IT <span>↗</span></a><a href="../hosting/index.html">Hosting <span>↗</span></a><a href="../design/index.html">Design <span>↗</span></a></aside><div class="prose">{body}<a class="button button-primary" href="../contact/index.html">Talk to our team <span>→</span></a></div></div></section><section class="contact-cta"><div class="shell cta-inner"><div><p class="eyebrow light"><span></span> Let’s make progress</p><h2>Got something<br>in mind?</h2></div><a class="round-link" href="../contact/index.html">Start a<br>conversation <span>↗</span></a></div></section></main><footer class="site-footer"><div class="shell"><div class="footer-top"><a class="brand brand-footer" href="../index.html"><img src="../audit/assets/original-path/wp-content/uploads/2019/09/logo-dark.webp" alt="Three AM Web + IT"></a><p>Web, IT, hosting and design —<br>all in one place.</p><a class="footer-email" href="mailto:info@threeam.com.au">info@threeam.com.au <span>↗</span></a></div><div class="footer-bottom"><span>© 2026 Three AM Web + IT</span><div><a href="../payment-policy/index.html">Payment policy</a></div></div></div></footer><script src="../script.js"></script></body></html>'''
pages={
'it':('IT Solutions','IT services and consulting from Three AM Web + IT.','IT solutions','Technology that keeps your business <em>connected.</em>','We provide a comprehensive range of IT services and consulting.','../assets/illustrations/it-network.svg','Stylised connected devices and network nodes.', '''<p class="eyebrow"><span></span> Practical IT support</p><h2>IT solutions tailored to your business.</h2><p>From connectivity and business email to security and server solutions, we can help put the right technology in place.</p><h3>NBN, ADSL and phone</h3><p>We can provision your business phone and internet connections, and ensure you get the right connection for your needs and budget.</p><h3>Servers</h3><p>With extensive experience with the Windows Server platform, we can tailor a solution to your needs, from file serving to Exchange and Hyper-V solutions.</p><h3>Anti-virus, email and Office 365</h3><p>Three AM are authorised resellers of Trend Micro and the AVG range of Business Anti-virus products. We can also help set up business email and Office 365 productivity tools.</p>'''),
'hosting':('Web Hosting','Australian-based web hosting and email solutions from Three AM.','Hosting','Hosting that keeps the essentials <em>running.</em>','We provide complete web hosting and email solutions.','../assets/illustrations/hosting-cloud.svg','Stylised cloud and server hosting illustration.', '''<p class="eyebrow"><span></span> Reliable foundations</p><h2>Hosting and email without the runaround.</h2><p>Located in a secure data centre in Sydney, our Australian-based cPanel servers feature RAID redundancy, nightly backups and automated security upgrades.</p><h3>Latest technology</h3><p>Our CentOS Linux servers use PHP8 and mySQL/MariaDB, and undergo regular upgrades to keep pace with current technology.</p><h3>Flexible when you grow</h3><p>We monitor accounts and aim to ensure upgrades occur before limits are met. If we expect your account to exceed limits, we will contact you to discuss options.</p><h3>Domains and premium hosting</h3><p>We can provide domain names and renewals, managed VPS hosting, and premium shared-server options.</p>'''),
'design':('Design','Graphic and digital design solutions from Three AM Web + IT.','Design','Design that gives your brand a <em>clear voice.</em>','Providing complete graphic design and corporate identity packages, or one-off design and print jobs.','../audit/assets/original-path/wp-content/uploads/2024/03/danni-stephens-legal-logo.png','Danni Stephens Legal branding project.', '''<p class="eyebrow"><span></span> Graphic and digital design</p><h2>Useful design, made with your business in mind.</h2><p>We provide corporate identity, graphic design, print and digital design to help you communicate with confidence.</p><h3>Logo design</h3><p>A logo represents your brand and everything you do. We listen to your requirements, learn about your business, research the industry, then develop concepts.</p><h3>Print design</h3><p>We can help with business cards, letterheads, brochures and flyers, including print formats and finishes that help your materials stand out.</p><h3>Digital design</h3><p>We design professional email signatures, HTML email templates and digital-signage solutions.</p>''')}
for slug,args in pages.items():
 p=Path(slug)/'index.html';p.parent.mkdir(exist_ok=True);p.write_text(shell(*args,active={'it':'IT','hosting':'Hosting','design':'Design'}[slug]))
